import { tenantProjectionToValue } from './tenant.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('tenantProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    name: 'value-name',
    root: 'value-root',
    domain: 'value-domain',
    enabled: 'value-enabled',
    markForDelete: 'value-markForDelete',
    markForDeleteTime: 'value-markForDeleteTime',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(tenantProjectionToValue(null)).toBeNull();
    expect(tenantProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(tenantProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      name: 'value-name',
      root: 'value-root',
      domain: 'value-domain',
      enabled: 'value-enabled',
      markForDelete: 'value-markForDelete',
      markForDeleteTime: 'value-markForDeleteTime',
      version: 'value-version',
    } as any;
    expect(tenantProjectionToValue(projection)).toEqual(value);
  });
});
